using Port = std::variant<PortNum, PortName>;
auto valid_port = overloads{
    [](PortNum n)  { return n > 0 && n < 65536; },       // choose: one branch each
    [](PortName s) { return !s.empty() && s.size() < 64; }};
bool ok = std::visit(valid_port, port);
auto valid = [](Config const& c) {                       // divide over fields
    return has_host(c.host) && std::visit(valid_port, c.port);
};

