template <class T, std::predicate<T const&>... Ps>
constexpr bool all_of(T const& v, Ps const&... rule) {   // divide + conquer
    return (rule(v) && ...);
}
struct PortRange { int lo, hi;
    bool operator()(int p) const { return p >= lo && p <= hi; } };
static_assert(all_of(42, PortRange{1, 65535}));
